from rest_framework import serializers
from django.contrib.auth import get_user_model, authenticate

User = get_user_model()


class RegisterSerializer(serializers.ModelSerializer):
    name      = serializers.CharField(required=False, allow_blank=True)
    password  = serializers.CharField(write_only=True, min_length=8)
    password2 = serializers.CharField(write_only=True)

    class Meta:
        model  = User
        fields = ['name', 'username', 'email', 'password', 'password2']

    def validate(self, attrs):
        if attrs['password'] != attrs.pop('password2'):
            raise serializers.ValidationError({'password': 'Passwords do not match.'})
        return attrs

    def create(self, validated_data):
        name = validated_data.pop('name', '')
        user = User.objects.create_user(**validated_data)
        user.first_name = name
        user.save()
        return user


class LoginSerializer(serializers.Serializer):
    email    = serializers.EmailField()
    password = serializers.CharField(write_only=True)

    def validate(self, attrs):
        user = authenticate(username=attrs['email'], password=attrs['password'])
        if not user:
            raise serializers.ValidationError('Invalid email or password.')
        attrs['user'] = user
        return attrs


class UserProfileSerializer(serializers.ModelSerializer):
    class Meta:
        model  = User
        fields = ['id', 'username', 'email', 'first_name', 'last_name', 'bio', 'avatar', 'date_joined']
        read_only_fields = ['id', 'email', 'date_joined']


class ChangePasswordSerializer(serializers.Serializer):
    old_password = serializers.CharField(write_only=True)
    new_password = serializers.CharField(write_only=True, min_length=8)

    def validate_old_password(self, value):
        user = self.context['request'].user
        if not user.check_password(value):
            raise serializers.ValidationError('Old password is incorrect.')
        return value

@action(detail=True, methods=['patch'], url_path='toggle_status')
def toggle_status(self, request, pk=None):
    """Cycle through pending → in_progress → done → pending."""
    todo = self.get_object()
    cycle = {
        'pending':     'in_progress',
        'in_progress': 'done',
        'done':        'pending',
    }
    todo.status = cycle[todo.status]
    todo.save()
    self._invalidate_cache()
    return Response(TodoStatusSerializer(todo).data)

@action(detail=False, methods=['get'], url_path='overdue')
def overdue(self, request):
    """Return all overdue todos for the current user."""
    from datetime import date
    overdue_todos = Todo.objects.filter(
        user=request.user,
        due_date__lt=date.today()
    ).exclude(status='done')
    serializer = self.get_serializer(overdue_todos, many=True)
    return Response(serializer.data)

@action(detail=False, methods=['get'], url_path='summary')
def summary(self, request):
    """Return count of todos grouped by status."""
    from django.db.models import Count
    data = (
        Todo.objects
        .filter(user=request.user)
        .values('status')
        .annotate(count=Count('id'))
    )
    return Response(data)

